package com.pulsefit.attendance;
import java.time.*; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.client.RestClient;
@RestController @RequestMapping("/api/attendance") public class AttendanceController { private final AttendanceRepository repo; private final RestClient.Builder rb; public AttendanceController(AttendanceRepository r,RestClient.Builder b){repo=r;rb=b;}
 @PostMapping("/check-in") public ResponseEntity<?> checkIn(@RequestBody CheckInRequest r){if(r.memberId()==null||r.facility()==null||r.facility().isBlank())return ResponseEntity.badRequest().body(Map.of("message","memberId and facility are required")); MemberDto member; try{member=rb.build().get().uri("http://MEMBER-SERVICE/internal/members/{id}",r.memberId()).retrieve().body(MemberDto.class);}catch(Exception e){return ResponseEntity.status(404).body(Map.of("message","Member not found"));} if(member==null||!"ACTIVE".equalsIgnoreCase(member.status()))return ResponseEntity.status(403).body(Map.of("message","Member is not active")); SubscriptionDto sub; try{sub=rb.build().get().uri("http://SUBSCRIPTION-SERVICE/internal/member/{id}/active",r.memberId()).retrieve().body(SubscriptionDto.class);}catch(Exception e){return ResponseEntity.status(403).body(Map.of("message","No active subscription"));} Attendance a=new Attendance();a.setMemberId(r.memberId());a.setSubscriptionId(sub.id());a.setFacility(r.facility());a.setCheckInTime(LocalDateTime.now());return ResponseEntity.status(201).body(repo.save(a));}
 @GetMapping("/member/{memberId}") public List<Attendance> history(@PathVariable Long memberId){return repo.findByMemberIdOrderByCheckInTimeDesc(memberId);} @GetMapping public List<Attendance> all(){return repo.findAll();}
 public record CheckInRequest(Long memberId,String facility){} public record MemberDto(Long id,String name,String email,String phone,LocalDate dateOfBirth,String status){} public record SubscriptionDto(Long id,Long memberId,Long planId,LocalDate startDate,LocalDate endDate,String status){}
}
